"use client"

import React from "react"
import {
    SiGoogledrive,
    SiYoutube,
    SiVimeo,
    SiCloudflare,
} from "@icons-pack/react-simple-icons"
import { VideoHostPlatform } from "@/modules/types/enums/video-host-platform"
import { EnumChip } from "@/components/blocks/chips/EnumChip"
import type { EnumChipEntry } from "@/components/blocks/chips/EnumChip"
import type { WithClassNames } from "@/modules/types/base/class-name"

/**
 * The props for the _HostPlatformChip component — presentational; labels already resolved.
 * @param hostPlatform - The host platform of the lesson video.
 * @param labels - Already-localized label per host platform.
 */
export interface HostPlatformChipProps extends WithClassNames<undefined> {
    /** Host platform of the lesson video. */
    hostPlatform: VideoHostPlatform
    /** Already-localized label per host platform, keyed by {@link VideoHostPlatform}. */
    labels: Partial<Record<VideoHostPlatform, string>>
}

/**
 * A chip that displays the host platform of a lesson video (accent, brand icon +
 * label). Thin domain map over the shared {@link EnumChip} primitive.
 * @param props - {@link HostPlatformChipProps}
 */
export const _HostPlatformChip = ({ hostPlatform, labels, className }: HostPlatformChipProps) => {
    // `Other` is intentionally unhandled — EnumChip throws on it, matching the
    // original switch `default` throw. Hence Partial rather than a full Record.
    const map: Partial<Record<VideoHostPlatform, EnumChipEntry>> = {
        [VideoHostPlatform.Youtube]: { color: "accent", icon: <SiYoutube size={16} />, label: labels[VideoHostPlatform.Youtube] ?? "" },
        [VideoHostPlatform.GoogleDrive]: { color: "accent", icon: <SiGoogledrive size={16} />, label: labels[VideoHostPlatform.GoogleDrive] ?? "" },
        [VideoHostPlatform.Vimeo]: { color: "accent", icon: <SiVimeo size={16} />, label: labels[VideoHostPlatform.Vimeo] ?? "" },
        [VideoHostPlatform.CloudflareStream]: { color: "accent", icon: <SiCloudflare size={16} />, label: labels[VideoHostPlatform.CloudflareStream] ?? "" },
    }
    return <EnumChip value={hostPlatform} map={map} className={className} />
}

"use client"

import React from "react"
import { FilmStripIcon as FilmReelIcon, SparkleIcon } from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { SiTwitch as TwitchLogoIcon } from "@icons-pack/react-simple-icons"
import { LessonVideoKind } from "@/modules/types/enums/lesson-video-kind"
import { EnumChip } from "@/components/blocks/chips/EnumChip"
import type { EnumChipEntry } from "@/components/blocks/chips/EnumChip"
import type { WithClassNames } from "@/modules/types/base/class-name"

/**
 * The props for the LessonVideoKindChip component.
 * @param kind - The kind of the lesson video.
 */
export interface LessonVideoKindChipProps extends WithClassNames<undefined> {
    /** Lesson video kind from the API. */
    kind: LessonVideoKind
}

/**
 * Chip with a tooltip explaining the lesson video kind (raw stream, edited, premium).
 * Thin domain map over the shared {@link EnumChip} primitive (warning-toned, per-kind
 * icon + tooltip).
 */
export const LessonVideoKindChip = ({ kind, className }: LessonVideoKindChipProps) => {
    const t = useTranslations()
    const map: Record<LessonVideoKind, EnumChipEntry> = {
        [LessonVideoKind.RawStream]: {
            color: "warning",
            icon: <TwitchLogoIcon className="size-5" />,
            label: t("lessonVideoKind.rawStream.label"),
            tooltip: t("lessonVideoKind.rawStream.tooltip"),
        },
        [LessonVideoKind.EditedStream]: {
            color: "warning",
            icon: <SparkleIcon className="size-5" />,
            label: t("lessonVideoKind.editedStream.label"),
            tooltip: t("lessonVideoKind.editedStream.tooltip"),
        },
        [LessonVideoKind.PremiumRecord]: {
            color: "warning",
            icon: <FilmReelIcon className="size-5" />,
            label: t("lessonVideoKind.premiumRecord.label"),
            tooltip: t("lessonVideoKind.premiumRecord.tooltip"),
        },
    }
    return <EnumChip value={kind} map={map} className={className} />
}

"use client"

import React from "react"
import {
    SandpackProvider,
    SandpackLayout,
    SandpackCodeEditor,
    SandpackPreview,
    SandpackFileExplorer,
} from "@codesandbox/sandpack-react"
import type { SandpackFiles, SandpackTheme } from "@codesandbox/sandpack-react"
import type { WithClassNames } from "@/modules/types/base/class-name"

const sharedFont = {
    body: "-apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
    mono: "'Fira Code', 'Cascadia Code', 'JetBrains Mono', monospace",
    size: "13px",
    lineHeight: "1.6",
}

/** Editor dark theme — surface1 matches the platform page background to blend in. */
const darkTheme: SandpackTheme = {
    colors: {
        surface1: "oklch(12.00% 0.0033 185.90)",
        surface2: "oklch(16.00% 0.0033 185.90)",
        surface3: "oklch(22.00% 0.0033 185.90)",
        clickable: "#6b7280",
        base: "#d1d5db",
        disabled: "#4b5563",
        hover: "#e5e7eb",
        accent: "#2dd4bf",
        error: "#f87171",
        errorSurface: "#1f1212",
    },
    syntax: {
        plain: "#e5e7eb",
        comment: { color: "#6b7280", fontStyle: "italic" },
        keyword: "#c084fc",
        tag: "#f472b6",
        punctuation: "#9ca3af",
        definition: "#60a5fa",
        property: "#34d399",
        static: "#fbbf24",
        string: "#86efac",
    },
    font: sharedFont,
}

/** Editor light theme — surface1 matches the platform page background to blend in. */
const lightTheme: SandpackTheme = {
    colors: {
        surface1: "oklch(97.02% 0.0033 185.90)",
        surface2: "oklch(94.00% 0.0033 185.90)",
        surface3: "oklch(90.00% 0.0033 185.90)",
        clickable: "#71717a",
        base: "#27272a",
        disabled: "#a1a1aa",
        hover: "#18181b",
        accent: "#0d9488",
        error: "#dc2626",
        errorSurface: "#fef2f2",
    },
    syntax: {
        plain: "#27272a",
        comment: { color: "#a1a1aa", fontStyle: "italic" },
        keyword: "#9333ea",
        tag: "#db2777",
        punctuation: "#52525b",
        definition: "#2563eb",
        property: "#059669",
        static: "#b45309",
        string: "#15803d",
    },
    font: sharedFont,
}

/** Props for {@link SandpackPanel}. */
export interface SandpackPanelProps extends WithClassNames<undefined> {
    /** Assembled files map (stubs + github files + dynamic overrides). */
    files: SandpackFiles
    /** Extra npm dependencies merged from the lesson's package.json. */
    dependencies?: Record<string, string>
    /** When true, use the dark editor theme (follows the platform theme). */
    isDark?: boolean
}

/**
 * External resources injected into the preview iframe by Sandpack itself
 * (the bundler ignores <script>/<link> tags inside index.html). Loads Tailwind
 * v4 utilities (runtime DOM scan) + HeroUI v3 compiled styles via CDN.
 */
const EXTERNAL_RESOURCES = [
    "https://cdn.jsdelivr.net/npm/@tailwindcss/browser@4",
    "https://cdn.jsdelivr.net/npm/@heroui/styles@3/dist/heroui.min.css",
]

/** Live in-browser React sandbox (Sandpack) previewing the lesson's code files. */
export const SandpackPanel = ({ files, dependencies = {}, isDark = true, className }: SandpackPanelProps) => (
    <div className={className}>
        <SandpackProvider
            template="react-ts"
            theme={isDark ? darkTheme : lightTheme}
            files={files}
            customSetup={{ dependencies }}
            options={{
                recompileMode: "delayed",
                recompileDelay: 600,
                externalResources: EXTERNAL_RESOURCES,
                // load the embedded preview at /?sandbox=1 so lesson frontends that
                // split into Local/Sandbox render the multi-client Sandbox content;
                // frontends without the split simply ignore the query param.
                startRoute: "/?sandbox=1",
            }}
        >
            <SandpackLayout style={{ border: "none", borderRadius: 0, minHeight: 520, width: "100%" }}>
                {/* left half — source: file tree + code editor */}
                <SandpackFileExplorer style={{ width: 190, height: 520 }} />
                <SandpackCodeEditor showLineNumbers showTabs={false} showReadOnly={false} style={{ flex: 1, height: 520 }} />
                {/* right half — live UI preview */}
                <SandpackPreview showNavigator={false} showOpenInCodeSandbox style={{ flex: 1, height: 520 }} />
            </SandpackLayout>
        </SandpackProvider>
    </div>
)

import React from "react"
import { BuildingsIcon, LockIcon } from "@phosphor-icons/react"
import { Image } from "@/components/atoms/media/Image"
import { Typography, type TypographyIcon } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Callout } from "@/components/composites/feedback/Callout"
import { StackV } from "@/components/frames/Stack"

/**
 * `ConsultantProfileBody` — the full detail content of one consultant's profile:
 * photo, name+role, a pressable company row, the full bio, and either real
 * contact links once unlocked or a locked callout with a way to unlock them.
 * The detail sibling of `ConsultantCard`. `contactUnlocked` only changes which
 * content fills the last slot, not the outer frame.
 */

/** One way to reach this consultant once contact is unlocked — plain navigable data. */
export interface ConsultantProfileBodyContactLink {
    /** Stable React key. */
    key: string
    /** Display label, e.g. "hoa.nguyen@techcorp.vn" or "090 123 4567". */
    label: string
    /** Where the link goes — `mailto:`/`tel:`/`https:` etc. The atom renders it, never fetches it. */
    href: string
    /** Optional leading glyph (mail/phone/chat) as a COMPONENT, not JSX. */
    icon?: TypographyIcon
}

/** One consultant's full profile — plain data, the block builds the detail view from it. */
export interface ConsultantProfileBodyConsultant {
    /** Full name — the profile's accessible heading. */
    fullName: string
    /** Role/title at their company. Row disappears when absent. */
    jobTitle?: string
    /** Company name. The company row disappears when absent. */
    companyTitle?: string
    /** Full bio — rendered in full here, unlike `ConsultantCard`'s clamped teaser. */
    description?: string
    /** Photo URL. Empty/missing → `Image`'s own fallback glyph, never a blank frame. */
    avatarUrl?: string
    /** `true` → real `contactLinks` are shown. `false` → the locked callout is shown instead. */
    contactUnlocked: boolean
    /** Ways to reach this consultant. Only read when `contactUnlocked` is `true`. */
    contactLinks?: Array<ConsultantProfileBodyContactLink>
}

/** Props for {@link ConsultantProfileBody}. */
export interface ConsultantProfileBodyProps {
    /** The consultant whose profile this fills. */
    consultant: ConsultantProfileBodyConsultant
    /** Fired when the visitor presses the company row. Row is disabled without it. */
    onOpenCompany?: () => void
    /** Fired from the locked callout's CTA. No CTA renders without it. */
    onImproveCv?: () => void
    /** Locked-callout heading. Falls back to the block's own English copy when omitted. */
    lockedTitle?: string
    /**
     * Locked-callout body — the place to surface the required CV score (e.g.
     * "needs CV score >= 70"). Falls back to the block's own English copy when omitted.
     */
    lockedDescription?: string
    /** Locked-callout CTA label. Falls back to the block's own English copy when omitted. */
    lockedCtaLabel?: string
    /**
     * `true` → `Image` and every `Typography` line switch to their own shimmer, the
     * company button is disabled, and the contact fork shows a neutral shimmer
     * instead of picking a branch (see file header). There is no id to open yet.
     */
    isSkeleton?: boolean
}

/** Fixed copy for the locked-contact callout — block-owned wording (§14d.1), see file header. */
const LOCKED_TITLE = "Contact is locked"
const LOCKED_DESCRIPTION = "Improve your CV to unlock this consultant's contact information."
const LOCKED_CTA_LABEL = "Improve CV"

/**
 * The full profile-detail content for one consultant. See the file header for
 * the full contract, the fork between `ConsultantCard`'s tile shape and this
 * one, and the judgment calls behind the contact fork.
 *
 * @param props - {@link ConsultantProfileBodyProps}
 */
const ConsultantProfileBody = ({
    consultant,
    onOpenCompany,
    onImproveCv,
    lockedTitle,
    lockedDescription,
    lockedCtaLabel,
    isSkeleton = false,
}: ConsultantProfileBodyProps) => {
    const { fullName, jobTitle, companyTitle, description, avatarUrl, contactUnlocked, contactLinks } = consultant

    const nameRow = (
        <StackV gap={1} align="center" principle="name-handle"
            explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
            isSkeleton={isSkeleton} items={[
                () => (
                    <Typography
                        size="h4"
                        weight="bold"
                        align="center"
                        isSkeleton={isSkeleton}
                        text={fullName}

                    />
                ),
                ...(isSkeleton || jobTitle ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        align="center"
                        isSkeleton={isSkeleton}
                        text={jobTitle}

                    />
                )] : []),
            ]} />
    )

    // identity: centered photo, name+role, pressable company row
    const identity = (
        <StackV gap={4} align="center" principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            isSkeleton={isSkeleton} items={[
                () => (
                    <div className="w-28">
                        <Image
                            src={avatarUrl}
                            alt={fullName}
                            ratio="square"
                            radius="full"
                            isSkeleton={isSkeleton}

                        />
                    </div>
                ),
                () => nameRow,
                ...(isSkeleton || companyTitle ? [() => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="secondary"
                        size="sm"
                        label={companyTitle ?? ""}
                        prefixIcon={BuildingsIcon}
                        onPress={onOpenCompany}
                        isDisabled={isSkeleton || !onOpenCompany}

                    />
                )] : []),
            ]} />
    )

    // contact fork — see file header for why loading shimmers neutrally
    const contactFork = isSkeleton ? (
        <StackV gap={2} isSkeleton={isSkeleton} items={[
            () => <Typography size="sm" isSkeleton classNames={["w-1/2"]} />,
            () => <Typography size="sm" isSkeleton classNames={["w-1/3"]} />,
        ]} />
    ) : contactUnlocked ? (
        <StackV gap={2} isSkeleton={isSkeleton} items={(contactLinks ?? []).map((link) => () => (
            <Typography
                size="sm"
                isLink
                href={link.href}
                prefixIcon={link.icon}
                text={link.label}

            />
        ))} />
    ) : (
        <Callout
            status="warning"
            icon={LockIcon}
            title={lockedTitle ?? LOCKED_TITLE}
            description={lockedDescription ?? LOCKED_DESCRIPTION}
            actionLabel={onImproveCv ? (lockedCtaLabel ?? LOCKED_CTA_LABEL) : undefined}
            onAction={onImproveCv}


        />
    )

    return (
        <StackV
            gap={6}
            isSkeleton={isSkeleton}
            identity={{ tier: "block", component: "ConsultantProfileBody" }}
            items={[
                () => identity,
                // full bio — no clamp, unlike ConsultantCard's directory teaser
                ...(isSkeleton || description ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={description}

                    />
                )] : []),
                () => contactFork,
            ]}
        />
    )
}

export { ConsultantProfileBody }

"use client"

import React, {
    useState,
} from "react"
import {
    publicEnv,
} from "@/resources/env/public"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link BadgeImage}. */
export interface BadgeImageProps extends WithClassNames<undefined> {
    /**
     * MinIO object key (no leading slash), e.g. `badges/league/gold.png`. The
     * public URL is built from `publicEnv().minio`. When the object does not exist
     * yet (instructor hasn't uploaded the art), the image 404s and {@link fallback}
     * is shown instead — so the web upgrades automatically as art is uploaded.
     */
    objectKey: string
    /** Square render size in px (default 24). */
    size?: number
    /** Alt text for the badge. */
    alt: string
    /** Rendered while the MinIO image is missing / fails to load. */
    fallback: React.ReactNode
}

/**
 * Renders a badge image straight from MinIO, falling back to {@link fallback}
 * (e.g. a placeholder icon) when the object isn't uploaded yet. Lets the team draw
 * + upload real badge art incrementally without the UI ever showing a broken image.
 * @param props - {@link BadgeImageProps}
 */
export const BadgeImage = ({
    objectKey,
    size = 24,
    alt,
    fallback,
    className,
}: BadgeImageProps) => {
    // flips to true once the MinIO object fails to load (missing / not uploaded)
    const [failed, setFailed] = useState(false)

    // no real art yet → show the placeholder fallback
    if (failed) {
        return <>{fallback}</>
    }

    // public MinIO URL: <url>/<bucket>/<objectKey>
    const { url, bucket } = publicEnv().minio
    const src = `${url}/${bucket}/${objectKey}`
    return (
        <img
            src={src}
            alt={alt}
            width={size}
            height={size}
            loading="lazy"
            className={className}
            onError={() => setFailed(true)}
        />
    )
}
